  "claims": [
    {
      "claim": "All visible L1 gold records in human or clinically relevant populations report oral bioavailability at or above 24%, so the training contexts provide no affirmative human evidence below the 20% threshold.",
      "card_ids": ["C01","C02","C03","C04","C05","C06","C07","C08","C09","C10","C11","C12","C13","C14"]
    },
    {
      "claim": "The only sub-20% record is ampicillin 12% in fasted veal calves (C17), a low-transferability species-specific result; the same calf model gives amoxicillin 32% (C23), still above threshold.",
      "card_ids": ["C17","C23"]
    },
    {
      "claim": "L3 saxagliptin records show measurable oral AUC (about 137.77–153.05 ng·h/mL) for an adamantane-containing small molecule, supporting oral exposure of this structural class, although no IV comparator or absolute F is reported.",
      "card_ids": ["C24","C25","C26","C27","C30","C31","C32","C33","C34","C35"]
    },
    {
      "claim": "L3 leucine Tmax and lisdexamfetamine Cmax records demonstrate oral absorption/exposure but do not provide absolute bioavailability and are not threshold-relevant for the query.",
      "card_ids": ["C28","C29"]
    },
    {
      "claim": "The most transferable small basic-amine contexts—aminoglutethimide (≈100%), molsidomine (44–59%), and maraviroc (24–33%)—all exceed 20%.",
      "card_ids": ["C03","C04","C12","C15","C21"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": ["C24","C25","C26","C27","C28","C29","C30","C31","C32","C33","C34","C35"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability or matched oral-versus-IV exposure measurement for the query molecule.",
    "L3 records report AUC/Cmax without IV comparators, so they cannot quantify absolute F.",
    "First-pass metabolism of the adamantane primary amine is not directly measured.",
    "Full ionization at pH 7.4 (logD -0.82) leaves permeability uncertain, though small size and the lipophilic cage may compensate.",
    "Transfer from record contexts is based on structural analogy, not identical chemistry."
  ],
  "decision_summary": "Predicted high (F ≥ 20%) because all visible L1 gold records are positive (≥24%) and the most transferable small basic-amine contexts support adequate oral bioavailability; L3 oral-exposure records add supportive but non-quantitative context (saxagliptin AUC) and no affirmative low evidence appears. Confidence remains moderate because no direct query F measurement exists and the query is fully ionized at pH 7.4."
}

